// ===== 01_clean_products.js =====
// R7-Office macro: clean product catalog with formulas.
// Source: 'Товары_исходные' (A=Артикул, B=Наименование, C=Категория,
//          D=Производитель, E=Цена_закупки, F=Цена_розница, G=ЕдИзм)
// Target: 'Товары_очищенные' (same layout, formulas in each cell)
(function () {
    var SRC = 'Товары_исходные';
    var DST = 'Товары_очищенные';

    function getOrCreate(name) {
        var sheets = Api.GetAllSheets();
        for (var i = 0; i < sheets.length; i++) {
            if (sheets[i].GetName() === name) return sheets[i];
        }
        return Api.AddSheet(name);
    }

    var src = getOrCreate(SRC);
    var dst = getOrCreate(DST);
    var lr = src.GetUsedRange().GetLastRow();     // 0-indexed
    if (lr < 1) return;

    // Copy raw snapshot (header + rows). Formulas overwrite in next loop.
    dst.GetRange('A1:G' + (lr + 1)).SetValue(src.GetRange('A1:G' + (lr + 1)).GetValue());

    var S = "'" + SRC + "'!";

    for (var r = 1; r <= lr; r++) {
        var n = r + 1;

        // Артикул -> АРТ-XXX
        dst.GetRange('A' + n).SetFormula(
            '="АРТ-"&LEFT(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(' + S + 'A' + n +
            ',"№",""),"АРТ-",""),"АРТ_",""),"/","-"),3)'
        );

        // Наименование: strip (...) and Title Case
        dst.GetRange('B' + n).SetFormula(
            '=PROPER(TRIM(IFERROR(LEFT(' + S + 'B' + n + ',FIND("(",' + S + 'B' + n +
            ')-1),' + S + 'B' + n + ')))'
        );

        // Категория via VLOOKUP -> Справочники!A:B
        dst.GetRange('C' + n).SetFormula(
            '=IFERROR(VLOOKUP(' + S + 'C' + n +
            ',\'Справочники\'!$A$2:$B$20,2,FALSE),' + S + 'C' + n + ')'
        );

        // Производитель: Title Case
        dst.GetRange('D' + n).SetFormula(
            '=PROPER(TRIM(' + S + 'D' + n + '))'
        );

        // Цена_закупки: strip spaces/руб, comma -> dot
        dst.GetRange('E' + n).SetFormula(
            '=IFERROR(VALUE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(' +
            S + 'E' + n + '," ",""),"руб.",""),"руб",""),",",".")),0)'
        );

        // Цена_розница
        dst.GetRange('F' + n).SetFormula(
            '=IFERROR(VALUE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(' +
            S + 'F' + n + '," ",""),"руб.",""),"руб",""),",",".")),0)'
        );

        // Единица_измерения -> шт.
        dst.GetRange('G' + n).SetFormula(
            '=IFERROR(VLOOKUP(' + S + 'G' + n +
            ',\'Справочники\'!$D$2:$E$10,2,FALSE),"шт.")'
        );

        // Валидация: розница >= закупки
        dst.GetRange('H1').SetValue('Проверка_цены');
        dst.GetRange('H' + n).SetFormula(
            '=IF(F' + n + '>=E' + n + ',"OK","Розница ниже закупки")'
        );

        // Валидация: артикул уникален
        dst.GetRange('I1').SetValue('Проверка_уникальности');
        dst.GetRange('I' + n).SetFormula(
            '=IF(COUNTIF($A$2:$A$' + (lr + 1) + ',A' + n + ')=1,"OK","Дубликат")'
        );
    }
})();

// ===== 02_clean_suppliers.js =====
// R7-Office macro: clean suppliers.
// Source: 'Поставщики_исходные' A=ID B=Название C=ИНН D=КПП E=Телефон
//          F=Email G=Адрес
// Target: A..G cleaned, H=Индекс, I=Адрес_остаток, J/K = validations.
(function () {
    var SRC = 'Поставщики_исходные';
    var DST = 'Поставщики_очищенные';

    function getOrCreate(name) {
        var sheets = Api.GetAllSheets();
        for (var i = 0; i < sheets.length; i++) {
            if (sheets[i].GetName() === name) return sheets[i];
        }
        return Api.AddSheet(name);
    }

    // classic Excel trick: extract digits from a text cell
    function digitsFormula(ref) {
        return 'SUMPRODUCT(MID(0&' + ref + ',LARGE(INDEX(ISNUMBER(--MID(' + ref +
               ',ROW(INDIRECT("1:"&LEN(' + ref + '))),1))*ROW(INDIRECT("1:"&LEN(' + ref +
               '))),0),ROW(INDIRECT("1:"&LEN(' + ref + '))))+1,1)*10^ROW(INDIRECT("1:"&LEN(' + ref + ')))/10)';
    }

    var src = getOrCreate(SRC);
    var dst = getOrCreate(DST);
    var lr = src.GetUsedRange().GetLastRow();
    if (lr < 1) return;

    dst.GetRange('A1:G' + (lr + 1)).SetValue(src.GetRange('A1:G' + (lr + 1)).GetValue());
    dst.GetRange('H1').SetValue('Индекс');
    dst.GetRange('I1').SetValue('Адрес_остаток');
    dst.GetRange('J1').SetValue('Проверка_ИНН');
    dst.GetRange('K1').SetValue('Проверка_Email');

    var S = "'" + SRC + "'!";

    for (var r = 1; r <= lr; r++) {
        var n = r + 1;

        // ИНН: digits only (formula). Note: leading zeros are lost, INN never start with 0.
        dst.GetRange('C' + n).SetFormula('=' + digitsFormula(S + 'C' + n));

        // Телефон: digits -> +7 (XXX) XXX-XX-XX
        var ph = S + 'E' + n;
        var phDigits = 'TEXT(' + digitsFormula(ph) + ',"00000000000")';
        dst.GetRange('E' + n).SetFormula(
            '=IF(LEN(' + phDigits + ')=11,"+7 ("&MID(' + phDigits + ',2,3)&") "&MID(' +
            phDigits + ',5,3)&"-"&MID(' + phDigits + ',8,2)&"-"&MID(' + phDigits + ',10,2),' + ph + ')'
        );

        // Email: strip spaces
        dst.GetRange('F' + n).SetFormula('=TRIM(' + S + 'F' + n + ')');

        // Адрес -> Индекс (6 digits) + остаток
        dst.GetRange('H' + n).SetFormula(
            '=IF(ISNUMBER(VALUE(LEFT(TRIM(' + S + 'G' + n + '),6))),LEFT(TRIM(' + S + 'G' + n + '),6),"")'
        );
        dst.GetRange('I' + n).SetFormula(
            '=TRIM(MID(TRIM(' + S + 'G' + n + '),7,255))'
        );

        // Валидация ИНН: длина 10 или 12
        dst.GetRange('J' + n).SetFormula(
            '=IF(OR(LEN(C' + n + ')=10,LEN(C' + n + ')=12),"OK","Ошибка ИНН")'
        );

        // Валидация Email: есть @ и точка после @
        dst.GetRange('K' + n).SetFormula(
            '=IF(AND(ISNUMBER(FIND("@",F' + n + ')),ISNUMBER(FIND(".",MID(F' + n +
            ',FIND("@",F' + n + ')+1,255)))),"OK","Ошибка Email")'
        );
    }
})();

// ===== 03_clean_sales.js =====
// R7-Office macro: clean sales.
// Source: 'Продажи_исходные' A=Дата B=Артикул C=Количество D=Цена_продажи
//          E=ID_клиента F=ID_поставщика G=Статус
// Target: H=Розничная_цена, I=Категория (VLOOKUP in Товары_очищенные)
(function () {
    var SRC = 'Продажи_исходные';
    var DST = 'Продажи_очищенные';

    function getOrCreate(name) {
        var sheets = Api.GetAllSheets();
        for (var i = 0; i < sheets.length; i++) {
            if (sheets[i].GetName() === name) return sheets[i];
        }
        return Api.AddSheet(name);
    }

    var src = getOrCreate(SRC);
    var dst = getOrCreate(DST);
    var lr = src.GetUsedRange().GetLastRow();
    if (lr < 1) return;

    dst.GetRange('A1:G' + (lr + 1)).SetValue(src.GetRange('A1:G' + (lr + 1)).GetValue());
    dst.GetRange('H1').SetValue('Розничная_цена');
    dst.GetRange('I1').SetValue('Категория_товара');
    dst.GetRange('J1').SetValue('Проверка_цены');

    var S = "'" + SRC + "'!";

    for (var r = 1; r <= lr; r++) {
        var n = r + 1;

        // Дата MM/DD/YYYY -> DATE(yyyy, mm, dd)
        dst.GetRange('A' + n).SetFormula(
            '=DATE(RIGHT(' + S + 'A' + n + ',4),LEFT(' + S + 'A' + n + ',2),MID(' + S + 'A' + n + ',4,2))'
        );

        // Артикул -> АРТ-XXX (same cleaning as products)
        dst.GetRange('B' + n).SetFormula(
            '="АРТ-"&LEFT(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(' + S + 'B' + n +
            ',"№",""),"АРТ-",""),"АРТ_",""),"/","-"),3)'
        );

        // Количество -> number (strips "шт", spaces, etc.)
        dst.GetRange('C' + n).SetFormula(
            '=IFERROR(VALUE(TRIM(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(' +
            S + 'C' + n + '," шт.","")," шт",""),"шт.",""),"шт",""))),0)'
        );

        // Цена_продажи -> RUB. Rates: $=95, €=100, ₽=1.
        dst.GetRange('D' + n).SetFormula(
            '=IF(LEFT(' + S + 'D' + n + ',1)="$",VALUE(MID(' + S + 'D' + n + ',2,255))*95,' +
            'IF(LEFT(' + S + 'D' + n + ',1)="€",VALUE(MID(' + S + 'D' + n + ',2,255))*100,' +
            'VALUE(SUBSTITUTE(SUBSTITUTE(' + S + 'D' + n + ',"₽","")," ",""))))'
        );

        // Статус через VLOOKUP
        dst.GetRange('G' + n).SetFormula(
            '=IFERROR(VLOOKUP(' + S + 'G' + n +
            ',\'Справочники\'!$G$2:$H$15,2,FALSE),' + S + 'G' + n + ')'
        );

        // VLOOKUP в каталог: розничная цена = колонка 6, категория = колонка 3
        dst.GetRange('H' + n).SetFormula(
            '=IFERROR(VLOOKUP(B' + n + ',\'Товары_очищенные\'!$A$1:$G$1000,6,FALSE),"нет в каталоге")'
        );
        dst.GetRange('I' + n).SetFormula(
            '=IFERROR(VLOOKUP(B' + n + ',\'Товары_очищенные\'!$A$1:$G$1000,3,FALSE),"нет в каталоге")'
        );

        // Валидация: цена продажи >= закупочной не проверяется (закупки нет в продажах),
        // поэтому проверяем только что цена положительна
        dst.GetRange('J' + n).SetFormula(
            '=IF(D' + n + '>0,"OK","Некорректная цена")'
        );
    }
})();

